const merr = msg => { const e = $('#merr'); if (e) { e.textContent = msg; e.hidden = false; } };
function tryM(fn, ok) { try { const r = fn(); ui.modal = null; toast(typeof ok === 'function' ? ok(r) : ok); render(); } catch (e) { if (isAppErr(e)) merr(e.message); else throw e; } }
