  cmov: () => { const m = ui.modal; tryM(() => api.registrarMov(me(), { folio: m.folio, personaId: m.pid, tipo: m.t, idVerificado: m.t === 'salida' ? true : V('mv-id') === true, materialOk: V('mv-mat') === undefined ? undefined : V('mv-mat'), motivo: V('mv-mot') || '', obs: V('mv-obs') }), r => `${m.t === 'entrada' ? 'Entrada' : 'Salida'} registrada · ${nowHM()}`); ui.qr = null; },
  qrej: d => { $('#qrref').value = d.tk; verificarQR(d.tk); },
